override fun close() {
    synchronized(lock) {
        if (closed) return@synchronized
        closed = true

        close(writeDescriptor)
        try {
            readFromPipe()
        } catch (_: Exception) {
            // Ignore errors during pipe teardown — the descriptor may have been
            // externally closed and reassigned by the OS.
        }
        close(readDescriptor)
    }
}
