void connect(const std::string &host, int port, int timeout_ms = 0) {
    close();
    struct addrinfo hints {};
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;      // To work with IPv4, IPv6, and so on
    hints.ai_socktype = SOCK_STREAM;  // TCP
    hints.ai_flags = AI_NUMERICSERV;  // port passed as as numeric value
    hints.ai_protocol = 0;

    struct timeval tv;
    tv.tv_sec = timeout_ms / 1000;
    tv.tv_usec = (timeout_ms % 1000) * 1000;

    auto port_str = std::to_string(port);
    struct addrinfo *addrinfo_result;
    auto rv = ::getaddrinfo(host.c_str(), port_str.c_str(), &hints, &addrinfo_result);
    if (rv != 0) {
        throw_spdlog_ex(fmt_lib::format("::getaddrinfo failed: {}", gai_strerror(rv)));
    }

    // Try each address until we successfully connect(2).
    int last_errno = 0;
    for (auto *rp = addrinfo_result; rp != nullptr; rp = rp->ai_next) {
#if defined(SOCK_CLOEXEC)
        const int flags = SOCK_CLOEXEC;
#else
        const int flags = 0;
#endif
        socket_ = ::socket(rp->ai_family, rp->ai_socktype | flags, rp->ai_protocol);
        if (socket_ == -1) {
            last_errno = errno;
            continue;
        }
        ::fcntl(socket_, F_SETFD, FD_CLOEXEC);
        if (connect_socket_with_timeout(socket_, rp->ai_addr, rp->ai_addrlen, timeout_ms) == 0) {
            last_errno = 0;
            break;
        }
        last_errno = errno;
        ::close(socket_);
        socket_ = -1;
    }
    ::freeaddrinfo(addrinfo_result);
    if (socket_ == -1) {
        throw_spdlog_ex("::connect failed", last_errno);
    }

    if (timeout_ms > 0) {
        // Set timeouts for send and recv
        ::setsockopt(socket_, SOL_SOCKET, SO_RCVTIMEO, (const char *)&tv, sizeof(tv));
        ::setsockopt(socket_, SOL_SOCKET, SO_SNDTIMEO, (const char *)&tv, sizeof(tv));
    }

    // set TCP_NODELAY
    int enable_flag = 1;
    ::setsockopt(socket_, IPPROTO_TCP, TCP_NODELAY, reinterpret_cast<char *>(&enable_flag),
                 sizeof(enable_flag));

    // prevent sigpipe on systems where MSG_NOSIGNAL is not available
#if defined(SO_NOSIGPIPE) && !defined(MSG_NOSIGNAL)
    ::setsockopt(socket_, SOL_SOCKET, SO_NOSIGPIPE, reinterpret_cast<char *>(&enable_flag),
                 sizeof(enable_flag));
#endif

#if !defined(SO_NOSIGPIPE) && !defined(MSG_NOSIGNAL)
#error "tcp_sink would raise SIGPIPE since neither SO_NOSIGPIPE nor MSG_NOSIGNAL are available"
#endif
}
